            if (-not $jsonLine -or $LASTEXITCODE -ne 0) { throw 'Local catalog preflight failed before the Fit Launcher handoff.' }
            $availableGames = @((($jsonLine -replace '^AFITGIRL_AVAILABLE_JSON=','') | ConvertFrom-Json))
